from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with register blocking and vectorization
matrix_mult_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Block and tile sizes
    constexpr int BLOCK_SIZE = 16;
    constexpr int TILE_SIZE = 4;

    // Shared memory for tiles
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Thread indices
    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    // Thread position within block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Register block for accumulation
    float c[TILE_SIZE][TILE_SIZE] = {{0}};

    // Prefetch first tile
    int a_col = tx * TILE_SIZE;
    int b_row = ty * TILE_SIZE;

    float4 a_val, b_val;

    // Loop over tiles
    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; tile++) {
        // Prefetch next tile while computing current
        int next_tile = tile + 1;
        int next_a_col = next_tile * BLOCK_SIZE + tx * TILE_SIZE;
        int next_b_row = next_tile * BLOCK_SIZE + ty * TILE_SIZE;

        // Load tile of A into shared memory with vectorization
        if (row < N && next_a_col < N) {
            a_val = *reinterpret_cast<const float4*>(&A[row * N + next_a_col]);
        } else {
            a_val.x = a_val.y = a_val.z = a_val.w = 0.0f;
        }

        // Load tile of B into shared memory with vectorization
        if (next_b_row < N && col < N) {
            b_val = *reinterpret_cast<const float4*>(&B[next_b_row * N + col]);
        } else {
            b_val.x = b_val.y = b_val.z = b_val.w = 0.0f;
        }

        // Load current tile into shared memory
        if (row < N && a_col < N) {
            *reinterpret_cast<float4*>(&As[ty][tx * TILE_SIZE]) = 
                *reinterpret_cast<const float4*>(&A[row * N + a_col]);
        } else {
            As[ty][tx * TILE_SIZE] = 0.0f;
            As[ty][tx * TILE_SIZE + 1] = 0.0f;
            As[ty][tx * TILE_SIZE + 2] = 0.0f;
            As[ty][tx * TILE_SIZE + 3] = 0.0f;
        }

        // Load current tile of B into shared memory with bank conflict avoidance
        if (b_row < N && col < N) {
            for (int i = 0; i < TILE_SIZE; i++) {
                Bs[ty * TILE_SIZE + i][tx] = B[(b_row + i) * N + col];
            }
        } else {
            for (int i = 0; i < TILE_SIZE; i++) {
                Bs[ty * TILE_SIZE + i][tx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial sums using register blocking
        for (int k = 0; k < BLOCK_SIZE; k++) {
            float a_reg[TILE_SIZE];
            float b_reg[TILE_SIZE];

            // Load from shared memory to registers
            for (int i = 0; i < TILE_SIZE; i++) {
                a_reg[i] = As[ty][k * TILE_SIZE + i];
                b_reg[i] = Bs[k][tx * TILE_SIZE + i];
            }

            // Accumulate results in registers
            for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
                    c[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }

        __syncthreads();

        // Store next tile in shared memory for next iteration
        *reinterpret_cast<float4*>(&As[ty][tx * TILE_SIZE]) = a_val;

        for (int i = 0; i < TILE_SIZE; i++) {
            Bs[ty * TILE_SIZE + i][tx] = b_val.x;
            b_val = (float4){b_val.y, b_val.z, b_val.w, 0.0f};
        }

        a_col += BLOCK_SIZE;
        b_row += BLOCK_SIZE;
    }

    // Write result to output matrix
    if (row < N && col < N) {
        for (int i = 0; i < TILE_SIZE; i++) {
            for (int j = 0; j < TILE_SIZE; j++) {
                int out_row = row + i;
                int out_col = col + j;
                if (out_row < N && out_col < N) {
                    C[out_row * N + out_col] = c[i][j];
                }
            }
        }
    }
}

torch::Tensor matrix_mult_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, torch::kFloat32).to(A.device());

    // Use 16x16 thread blocks
    dim3 threadsPerBlock(4, 4);  // Each thread handles 4x4 tile
    dim3 blocksPerGrid((N + BLOCK_SIZE - 1) / BLOCK_SIZE,
                      (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matrix_mult_kernel<<<blocksPerGrid, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                          B.data_ptr<float>(), 
                                                          C.data_ptr<float>(), 
                                                          N);
    return C;
}
"""

